preConditionHook:
// EL's Average recomputes from scratch every bar (EL_Summation_Probe:
// fresh loop matched on 2,808/2,808 bars) -- no rolling accumulator, and
// the close series has real history, so no warm-up mirroring.
avgClose = 0.0;
for (int i = 0; i < (int)lookback; ++i) {
    avgClose += close[i];
}
avgClose /= (int)lookback;
